// Attendance calculators on the tool pages (generated by tools/build_seo_pages.py).
//
// Each calculator on a page is a [data-widget] element; the page supplies its
// wording in window.CALC_TEXT before loading this file. A wording entry is a
// string, or {one, other} where the number decides which one is used. The
// maths follows lib/features/reports/attendance_report_model.dart in the app
// repository (bunkable, classesToTarget), so the site and the app always give
// the same answer for the same numbers.
(function () {
  var T = window.CALC_TEXT;
  // Guards against 74.99999… from floating point turning into one class less.
  var EPS = 1e-9;

  function text(key, n) {
    var value = T[key];
    return typeof value === 'string' ? value : (n === 1 ? value.one : value.other);
  }
  function fill(template, values) {
    return template.replace(/\{(\w+)\}/g, function (_, key) { return values[key]; });
  }
  // Rounds down, so a percentage just under the target never reads as the target.
  function fmt(value) {
    return (Math.floor(value * 100 + EPS) / 100).toLocaleString(document.documentElement.lang);
  }
  function isCount(value) { return !isNaN(value) && value >= 0 && value % 1 === 0; }

  // How many more classes may be missed while staying at target.
  function canMiss(held, attended, target) {
    return Math.max(0, Math.floor(attended * 100 / target - held + EPS));
  }
  // How many classes in a row must be attended to get back to target.
  function mustAttend(held, attended, target) {
    var ratio = target / 100;
    return Math.max(0, Math.ceil((ratio * held - attended) / (1 - ratio) - EPS));
  }

  // Each returns [headline, detail, tone], or a string for invalid input.
  var KINDS = {
    standing: function (v) {
      if (v.held < 1) return text('wholeNumbers');
      if (v.attended > v.held) return text('attendedTooMany');
      var now = v.attended * 100 / v.held;
      var current = fill(text('current'), { pct: fmt(now) });
      if (now + EPS >= v.target) {
        var miss = canMiss(v.held, v.attended, v.target);
        if (miss === 0) {
          return [text('atEdge'), fill(text('atEdgeDetail'), { current: current, target: fmt(v.target) }), 'edge'];
        }
        return [fill(text('canMiss', miss), { n: miss, target: fmt(v.target) }),
          fill(text('canMissDetail'), { current: current, pct: fmt(v.attended * 100 / (v.held + miss)) }), 'good'];
      }
      if (v.target >= 100) return [text('unreachable'), current, 'bad'];
      var need = mustAttend(v.held, v.attended, v.target);
      return [fill(text('mustAttend', need), { n: need, target: fmt(v.target) }),
        fill(text('mustAttendDetail'), { current: current, pct: fmt((v.attended + need) * 100 / (v.held + need)) }), 'bad'];
    },

    plan: function (v) {
      if (v.total < 1) return text('wholeNumbers');
      var miss = Math.max(0, Math.floor(v.total * (1 - v.target / 100) + EPS));
      return [fill(text('planMiss', miss), { n: miss, total: v.total }),
        fill(text('planDetail'), { attend: v.total - miss, total: v.total }), 'good'];
    },

    whatif: function (v) {
      if (v.held < 1) return text('wholeNumbers');
      if (v.attended > v.held) return text('attendedTooMany');
      var after = v.attended * 100 / (v.held + v.skip);
      var most = canMiss(v.held, v.attended, v.target);
      var ok = after + EPS >= v.target;
      return [fill(text('whatif', v.skip), { n: v.skip, pct: fmt(after) }),
        fill(text(ok ? 'whatifAbove' : 'whatifBelow'), { target: fmt(v.target), m: most }), ok ? 'good' : 'bad'];
    },

    recover: function (v) {
      if (v.held + v.remaining < 1) return text('wholeNumbers');
      if (v.attended > v.held) return text('attendedTooMany');
      var final = v.held + v.remaining;
      var need = Math.max(0, Math.ceil(v.target / 100 * final - v.attended - EPS));
      if (need > v.remaining) {
        return [fill(text('recoverImpossible'), { rem: v.remaining, pct: fmt((v.attended + v.remaining) * 100 / final) }),
          fill(text('recoverImpossibleDetail'), { target: fmt(v.target) }), 'bad'];
      }
      if (need === 0) return [fill(text('recoverSafe'), { rem: v.remaining, target: fmt(v.target) }), '', 'good'];
      return [fill(text('recover', need), { n: need, rem: v.remaining }),
        fill(text('recoverDetail'), { m: v.remaining - need, target: fmt(v.target) }), 'good'];
    }
  };

  function attach(root) {
    var calculate = KINDS[root.dataset.widget];
    var box = root.querySelector('.result');
    function run() {
      var v = {};
      var blank = false;
      var counts = true;
      root.querySelectorAll('input').forEach(function (input) {
        var raw = input.value.trim();
        if (raw === '') blank = true;
        v[input.name] = Number(raw);
        if (input.name !== 'target' && !isCount(v[input.name])) counts = false;
      });
      if (blank) { box.hidden = true; return; }
      var result = !counts ? text('wholeNumbers')
        : (isNaN(v.target) || v.target <= 0 || v.target > 100) ? text('targetRange')
        : calculate(v);
      if (typeof result === 'string') result = [result, '', 'warn'];
      box.hidden = false;
      box.dataset.tone = result[2];
      box.querySelector('.result-headline').textContent = result[0];
      box.querySelector('.result-detail').textContent = result[1];
    }
    root.addEventListener('input', run);
    run();
  }

  document.querySelectorAll('[data-widget]').forEach(attach);
})();
